from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
ACT='Gabay na 30 minuto: 10 pag-unawa sa teksto, 8 pag-aayos ng halimbawa, 9 pagsulat, 3 pagbalik-tanaw.\n'
m.lesson(45,'Paghanap ng kakulangan at paghahalo gamit ang 5S at tatlong takda','Ipagpatuloy ang 5S at gawing nakikita ang kaibahan ng bagay at dami sa tatlong takda.',[
('Ihiwalay ang limang kilos','Pagbubukod ang paghiwalay ng kailangan at hindi at pag-alis ng hindi kailangan. Pag-aayos ang paglalagay ng kailangan upang madaling gamitin; paglilinis ang pag-alis ng dumi. Pagpapanatili ng kalinisan ang pagpapanatili ng resulta ng tatlo; disiplina ang paggawang nakagawian ng itinakdang kilos.'),
('Itakda ang lugar, bagay, at dami','Tatlong takda ang lugar, uri, at dami. Bukod sa estante, ipakita ang part number at pinapayagang dami. Mas madaling makita ang kulang, sobra, at paghahalo kapag may upper at lower limits.'),
('Huwag ipaghalo ang pag-aayos at pagtatapon','Huwag basta itapon ang hindi kilala o naka-hold; markahan at itanong. Halimbawa, kung may ibang piyesa sa estante ng terminal B, hindi sapat na ilipat sa bakante upang maiwasan ang pag-ulit. Itugma ang label at record at alamin kung bakit nahalo.')],['Paghiwalay ng kailangan at hindi at pag-alis ng hindi kailangan.','Pagpapanatili ng pagbubukod, ayos, at linis.','Pamamahalang nagtatakda ng lugar, bagay, at dami.','Pagtatakda at pagsunod sa dami o saklaw ng nakalagay.'],ACT+'Gumawa ng checklist ng terminal shelf na may lugar, part number, minimum8 at maximum24. Hiwalay na iulat kung5lamang at kung may ibang piyesa.',['Huwag basta itapon ang kemikal o naka-hold na produkto sa pag-aakalang hindi kailangan.'],'Ipagpatuloy ang 5S at gawing nakikita ang kaibahan ng bagay at dami sa tatlong takda.')
m.lesson(46,'Pagsuri sa edukasyon at PPE ayon sa trabaho','Tiyakin ang training requirements at tungkulin at iangkop ang PPE sa panganib.',[
('Matuto bago ang bagong trabaho','Sa pagpasok o pagbabago ng trabaho, tiyakin ang panganib, kagamitan, PPE, procedure, pre-start check, at emergency response. Sa hazardous work, nagkakaiba ayon sa kondisyon ang kwalipikasyon, skills course, at special education. Huwag pangalan lamang ng trabaho ang batayan kung maaari mong hawakan.'),
('Hindi pagpapabaya ang OJT','Tingnan ang paliwanag at demonstration, gawin sa aprubadong saklaw, at tumanggap ng feedback. Huwag magkunwaring nauunawaan dahil nakita; ipaliwanag sa sariling salita ang mahalagang procedure. Hindi awtomatikong kapalit ng legal education o qualification ang OJT.'),
('Piliin ayon sa panganib','Safety shoes laban sa nahuhulog, goggles laban sa lumilipad na bagay. Maaaring proteksiyon o sanhi ng pagkakahila ang guwantes ayon sa trabaho. Huwag ilapit ang cloth-gloved hand sa rotating drill press; sa kemikal, tiyakin ang chemical-compatible PPE at ventilation. Sa transport, suriin ang bigat, visibility, ruta, at takdang aids; lumayo sa ilalim at paligid ng suspended load. Sa casting, ihiwalay ang heat at dust; tiyakin ang heatstroke measures at angkop na dust protection.')],['Safety/health education na kailangan sa ilang hazardous tasks.','Edukasyong may paliwanag, aktuwal na pagsasanay, at feedback sa trabaho.','PPE na nagpoprotekta sa mata laban sa lumilipad na bagay at iba pa.','Pagkahila ng damit o katawan sa rotating part.'],ACT+'Gumawa ng mga tanong sa training, saklaw, PPE, inspeksiyon, at emergency contact bago humawak ng bagong makina. Ihambing ang guwantes sa rotating at chemical work.',['Huwag magpasya nang mag-isa sa mapanganib na operasyon dahil lamang may training at PPE.'],'Tiyakin ang training requirements at tungkulin at iangkop ang PPE sa panganib.')
m.lesson(47,'Pagbasa ng prohibition, warning, at evacuation signs','Basahin ang target, lugar, at uri ng sakuna bukod sa kulay at hugis.',[
('Mga hindi dapat gawin','Kabilang sa pulang prohibition ang no smoking, no open flame, no entry, do not touch, at not drinking water. Basahin ang general prohibition kasama ang paliwanag ng target. Tiyakin kung tao o sasakyan at anong kilos ang nililimitahan.'),
('Alamin ang panganib','Kabilang sa dilaw na warning ang electric shock, slippery, step, fall, at overhead obstruction. Hindi ibig sabihing malayang pumasok dahil warning sa halip na prohibition. Tingnan ang lugar, working conditions, at kasamang tagubilin at tiyak na sabihin ang panganib.'),
('Lokasyon sa emergency','Gabay ang extinguisher, AED, at evacuation signs upang hanapin ang equipment o pupuntahan. Huwag pag-isahin ang malawak na evacuation area, building, at tsunami refuge; tiyakin ayon sa sakuna at ruta sa trabaho. Sundin ang voice prompts o rescue personnel sa AED.')],['Tagubiling hindi dapat gawin ang partikular na kilos.','Sign na nagpapabatid ng presensiya ng panganib.','Paglipat mula panganib patungong ligtas na lugar.','Device na nagsusuri ng puso at gumagabay sa electric shock kung kailangan.'],ACT+'Itugma ang kahulugan at pagtiyak sa shock warning, extinguisher, at evacuation site sa sariling lugar. Isulat ang kondisyon sa pagpili sa dalawang magkaibang refuge.',['Huwag pumasok sa no-entry zone upang suriin ang sign.'],'Basahin ang target, lugar, at uri ng sakuna bukod sa kulay at hugis.')
m.lesson(48,'Pag-uugnay ng SDS at chemical labels sa trabaho','Itugma ang label/SDS at tiyakin muna ang ventilation, protection, at emergency response.',[
('Pictograms bilang gabay sa panganib','Iba-ibang hazard ang flame, corrosion, health hazard, environmental hazard, at exclamation mark. Maaaring marami sa isang lalagyan. Huwag mula larawan lamang ang concentration, PPE, o first aid; itugma ang product name sa label at SDS.'),
('Basahin ang kailangan bago gamitin','May hazard, handling/storage, exposure prevention, first aid, at spill response sa SDS. Patakbuhin ang local exhaust/ventilation at tiyakin ang angkop na PPE at waste container. Sundin ang nakatalagang gabay sa health management gaya ng special medical exams.'),
('Huwag hulaan ang hindi kilalang likido','Sa unlabeled na maliit na lalagyan, huwag kulay/amoy ang pagtukoy; i-hold. Maaaring maipon ang vapor sa organic-solvent tank, kaya huwag basta maglinis. Aprubadong procedure sa paglilipat, paghahalo, at leak response.')],['Safety data sheet ng chemical hazard at handling information.','Pagkalantad sa hazardous substance sa paglanghap o skin contact.','Equipment na humihigop ng hazardous air malapit sa pinagmulan.','Katangiang nakapipinsala sa balat, metal, at iba pa.'],ACT+'Sa hindi mabasang cleaning-liquid label, ayusin ang limang item: product name, SDS, ventilation, PPE, at waste. Sumulat ng use-hold report.',['Huwag amuyin o paghaluin upang makilala ang kemikal. Huwag basta pumasok sa tank.'],'Itugma ang label/SDS at tiyakin muna ang ventilation, protection, at emergency response.')
m.lesson(49,'Near-miss at pagpapabuti sa OSHMS','Ibahagi ang palatandaan kahit walang sugat at patuloy na suriin matapos ang hakbang.',[
('Iulat ang maliliit na palatandaan','Pag-aralan ang Heinrich1・29・300bilang pananaw sa major, minor, at near-miss relation. Hindi tiyak na ganoon ang bawat lugar o ligtas hanggang300. Itala ang mapanganib na paglapit at halos pagkahulog kahit walang sugat.'),
('Paikot na gawain ng organisasyon','Sa OSHMS, inuulit ang plan, do, check, at improve upang pamahalaan ang safety/health. Suriin ang bisa at natitirang risk at balikan kasama ang responsable at deadline. Hindi natatapos ang gawain sa rekord lamang.'),
('Huwag tiyaking ganap na ligtas','Ipagpalagay ang machine failure, human error, at sakuna at patuloy na pababain ang risk. Tingnan kung may bagong panganib matapos ang hakbang. Pagsamahin ang piniling KYT action at pagbabago sa equipment o proseso.')],['Pangyayaring hindi umabot sa aksidente ngunit may naramdamang panganib.','Sistema ng tuloy-tuloy na safety/health management.','Risk na natitira matapos ang hakbang.','Paglalagay ng natasa na problema sa susunod na kilos o plano.'],ACT+'Itala ang katotohanan sa piyesang halos nahulog sa paa ngunit walang pinsala. Gumawa ng prevention plan na hinati sa plan, do, check, improve.',['Huwag gamitin ang ratio bilang limitasyon kung hanggang kailan ligtas magtrabaho.'],'Ibahagi ang palatandaan kahit walang sugat at patuloy na suriin matapos ang hakbang.')
m.lesson(50,'Design, manufacturing, at logistics quality at 4M','Ihiwalay ang yugto ng quality at siyasatin ang pagbabago sa 4M gamit ang katotohanan.',[
('Mula pangangailangan ng kostumer','Quality ang antas ng pagtugon sa performance, safety, reliability, at iba pang pangangailangan ng kostumer, hindi kaginhawahan lamang ng gumagawa. Design quality ang tinatarget; manufacturing quality ang naisagawang disenyo; logistics quality ang produkto, dami, deadline, at kondisyon hanggang makarating.'),
('QCD at safety','Q:quality,C:cost,D:delivery. Kahit kasama ang safety S, huwag alisin ang safety device upang mahabol ang deadline. Ang rework ay may epekto sa oras at tiwala bukod sa material cost.'),
('Tingnan ang pagbabago sa 4M','Man:operator,Machine:equipment,Material:materyal,Method:paraan. Huwag tao lamang ang sisihin sa dagdag na depekto; ihambing ang material lot, tool state, setting change, at training. Kung sabay-sabay, itala ang oras at saklaw ng bawat pagbabago.')],['Quality na tinatakda bilang target sa disenyo.','Quality ng resultang naisagawa sa manufacturing.','Pananaw na pinagsasama ang quality,cost,delivery.','Pananaw ayon sa tao,equipment,materyal,paraan.'],ACT+'Ilista sa4Mang kondisyon ng dumaming crimp defects bago deadline. Gumawa ng hold/report plan na nagpapanatili sa customer requirements at safety.',['Huwag alisin ang safety at inspection requirements dahil sa deadline o cost.'],'Ihiwalay ang yugto ng quality at siyasatin ang pagbabago sa 4M gamit ang katotohanan.')
